export async function addSkillToLock(
  slug,
  entry,
  lockPath = getGlobalLockPath(),
) {
  const l = await readLock(lockPath)
  const existing = l.skills[slug]

  const mergedAgents = existing?.agents
    ? [...new Set([...existing.agents, ...(entry.agents || [])])]
    : entry.agents || []

  pushHistory(l, slug, entry)

  const history = l.skills[slug]?.history || []

  l.skills[slug] = {
    ...entry,
    agents: mergedAgents,
    installedAt: new Date().toISOString(),
    history,
  }

  await writeLock(l, lockPath)

  return l
}
